using System;

namespace Nosum.Domain.Common;

/// <summary>Base class of persisted entities that have their own identity.</summary>
public abstract class Entity
{
    /// <summary>Gets or sets the primary key. Generated by the application (time-ordered GUID), never by the database.</summary>
    public Guid Id { get; set; } = Guid.CreateVersion7();
}
